        List<Long> certIds = lockedMeasurements.stream().map(Measurement::certificateId).distinct().sorted().toList();
        for (Long certId : certIds) {
            Certificate cert = certificates.findByIdForUpdate(certId)
                    .orElseThrow(() -> ApiException.conflict("CERTIFICATE_MISSING",
                            "测量关联的证书不存在: " + certId));
            if (cert.revoked()) {
                throw ApiException.conflict("JOINT_BATCH_CONCURRENT_CONFLICT",
                        "联合批次校验通过后关联证书被撤销: certificateId=" + certId);
            }
        }
        for (String key : orderedKeys) {
            Measurement measurement = lockedMeasurements.stream()
                    .filter(m -> m.measurementKey().equals(key)).findFirst().orElseThrow();
            Certificate cert = certificates.findById(measurement.certificateId()).orElseThrow();
            if (!ReleaseRules.evaluate(measurement, cert, releaser).isEmpty()) {
                throw ApiException.conflict("JOINT_BATCH_CONCURRENT_CONFLICT",
                        "联合批次校验后测量状态发生并发变化: " + key);
            }
        }
        return lockedMeasurements;
    }

    /**
     * 同 requestId 重放裁决：jointBatchKey 相同且测量集合相同（换序视为同参）返回首次响应快照；异参 409。
     */
    private JointReleaseResponse replayOrConflict(JointReleaseBatch existing, String jointBatchKey,
                                                  Set<String> keySet) {
        Set<String> snapshotKeys = readSnapshot(existing.snapshotKeys());
        if (existing.jointBatchKey().equals(jointBatchKey) && snapshotKeys.equals(keySet)) {
            return new JointReleaseResponse(existing.jointBatchKey(), existing.requestId(),
                    existing.releasedBy(), existing.releasedAt(), List.copyOf(snapshotKeys() == null ? List.of() : List.of()));
        }
        throw ApiException.conflict("IDEMPOTENCY_PARAM_CONFLICT",
                "requestId 已用于不同参数的联合批次放行: " + existing.requestId());
    }

    private String writeSnapshot(List<String> orderedKeys) {
        try {
            return JSON.writeValueAsString(orderedKeys);
        } catch (JsonProcessingException ex) {
            throw ApiException.badRequest("测量键序列化失败");
        }
    }

    private Set<String> readSnapshot(String json) {
        try {
            return new LinkedHashSet<>(JSON.readerForListOf(String.class).readValue(json));
        } catch (JsonProcessingException ex) {
            throw ApiException.conflict("JOINT_BATCH_SNAPSHOT_CORRUPT", "联合批次响应快照损坏");
        }
    }
}

