        // 缺少 X-Actor-Id → 400
        mvc.perform(post("/api/joint-releases").contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"jointBatchKey":"JB-V4","requestId":"REQ-V4","keys":["A-1","A-1"]}"""))
                .andExpect(status().isBadRequest());
