1	package com.example.starter.calibration.service;
2	
3	import java.time.Instant;
4	import java.util.ArrayList;
5	import java.util.HashSet;
6	import java.util.LinkedHashSet;
7	import java.util.List;
8	import java.util.Set;
9	
10	import org.springframework.dao.DuplicateKeyException;
11	import org.springframework.stereotype.Service;
12	import org.springframework.transaction.annotation.Transactional;
13	
14	import com.example.starter.calibration.api.ApiException;
15	import com.example.starter.calibration.api.ItemFailure;
16	import com.example.starter.calibration.api.JointBatchRejectedException;
17	import com.example.starter.calibration.api.dto.JointReleaseDetailResponse;
18	import com.example.starter.calibration.api.dto.JointReleaseItemResponse;
19	import com.example.starter.calibration.api.dto.JointReleaseRequest;
20	import com.example.starter.calibration.api.dto.JointReleaseResponse;
21	import com.example.starter.calibration.model.Certificate;
22	import com.example.starter.calibration.model.JointReleaseBatch;
23	import com.example.starter.calibration.model.JointReleaseItem;
24	import com.example.starter.calibration.model.Measurement;
25	import com.example.starter.calibration.model.MeasurementStatus;
26	import com.example.starter.calibration.repo.CertificateRepository;
27	import com.example.starter.calibration.repo.JointReleaseRepository;
28	import com.example.starter.calibration.repo.MeasurementRepository;
29	import com.example.starter.calibration.repo.ReleaseRepository;
30	import com.fasterxml.jackson.core.JsonProcessingException;
31	import com.fasterxml.jackson.databind.ObjectMapper;
32	
33	/**
34	 * 跨仪器联合批次放行服务：2～20 条测量（可来自不同仪器）在一个事务内一致放行。
35	 * 校验规则与既有同仪器批量放行共享（{@link ReleaseRules}）。
36	 *
37	 * <p>两阶段裁决：
38	 * <ol>
39	 *   <li>无快照阶段：不加锁读取当前状态并校验，任一不满足整批 422 逐条返回原因，不写入任何记录；</li>
40	 *   <li>加锁复核阶段：按测量键字典序、证书 ID 字典序对相关行加 FOR UPDATE 行锁后重新读取，
41	 *       若与快照不一致（被其他批次放行、证书在本事务获锁前被撤销等），整批 409 回滚，不产生部分放行。</li>
42	 * </ol>
43	 * 由此证书撤销与放行按事务提交顺序裁决：撤销先提交则放行 409；放行先提交则历史固化、撤销不追溯。
44	 */
45	@Service
46	public class JointReleaseService {
47	
48	    /** 联合批次最小条数。 */
49	    static final int MIN_BATCH_SIZE = 2;
50	    /** 联合批次最大条数。 */
51	    static final int MAX_BATCH_SIZE = 20;
52	
53	    private static final ObjectMapper JSON = new ObjectMapper();
54	
55	    private final MeasurementRepository measurements;
56	    private final CertificateRepository certificates;
57	    private final ReleaseRepository releases;
58	    private final JointReleaseRepository jointReleases;
59	
60	    public JointReleaseService(MeasurementRepository measurements,
61	                               CertificateRepository certificates,
62	                               ReleaseRepository releases,
63	                               JointReleaseRepository jointReleases) {
64	        this.measurements = measurements;
65	        this.certificates = certificates;
66	        this.releases = releases;
67	        this.jointReleases = jointReleases;
68	    }
69	
70	    /**
71	     * 联合批次一致放行。
72	     * 任一测量不满足条件整批 422 逐条返回原因；并发冲突整批 409；
73	     * 同 requestId 且同 jointBatchKey、同测量集合（换序视为同参）重放返回首次成功响应快照；异参 409。
74	     */
75	    @Transactional
76	    public JointReleaseResponse release(JointReleaseRequest request, String actor) {
77	        String releaser = Inputs.requireText(actor, "X-Actor-Id");
78	        String jointBatchKey = Inputs.requireText(request == null ? null : request.jointBatchKey(),
79	                "jointBatchKey");
80	        String requestId = Inputs.requireText(request == null ? null : request.requestId(), "requestId");
81	        List<String> orderedKeys = requireKeys(request == null ? null : request.keys());
82	        Set<String> keySet = new LinkedHashSet<>(orderedKeys);
83	
84	        // 幂等：同 requestId 已存在成功批次时，同参回放首次快照，异参 409（失败不占键，故只会查到成功记录）
85	        JointReleaseBatch existing = jointReleases.findBatchByRequestId(requestId).orElse(null);
86	        if (existing != null) {
87	            return replayOrConflict(existing, jointBatchKey, keySet);
88	        }
89	
90	        // 阶段一：无锁快照校验，失败整批 422 且不写入任何记录（失败不占键）
91	        validateSnapshot(orderedKeys, releaser);
92	
93	        // 阶段二：对测量与证书行加锁后重新读取复核，期间状态被并发改变则整批 409 回滚。
94	        // 但若并发胜出者恰为同 requestId 同参的请求，按幂等语义回放其首次成功快照。
95	        List<Measurement> locked;
96	        try {
97	            locked = lockAndRecheck(orderedKeys, releaser);
98	        } catch (ApiException ex) {
99	            if (ex.getStatus() == org.springframework.http.HttpStatus.CONFLICT) {
100	                JointReleaseBatch winner = jointReleases.findBatchByRequestId(requestId).orElse(null);
101	                if (winner != null) {
102	                    return replayOrConflict(winner, jointBatchKey, keySet);
103	                }
104	            }
105	            throw ex;
106	        }
107	
108	        Instant releasedAt = Instant.now();
109	        String snapshot = writeSnapshot(orderedKeys);
110	        long jointBatchId;
111	        try {
112	            jointBatchId = jointReleases.insertBatch(jointBatchKey, requestId, releaser,
113	                    releasedAt, snapshot, releasedAt);
114	        } catch (DuplicateKeyException ex) {
115	            // 并发提交：joint_batch_key 或 request_id 唯一约束落败，以先落地批次为准回放或判冲突
116	            JointReleaseBatch winner = jointReleases.findBatchByRequestId(requestId)
117	                    .or(() -> jointReleases.findBatchByJointKey(jointBatchKey))
118	                    .orElseThrow(() -> ApiException.conflict("JOINT_BATCH_KEY_CONFLICT",
119	                            "联合批次键或请求键已被占用: " + jointBatchKey));
120	            return replayOrConflict(winner, jointBatchKey, keySet);
121	        }
122	
123	        // 既有单条放行历史共享 release_record，batch_id 直接使用 jointBatchKey 关联，
124	        // 每条测量自身放行历史与既有单条查询保持兼容。
125	        String historyBatchId = jointBatchKey;
126	        for (Measurement measurement : locked) {
127	            measurements.markReleased(measurement.id());
128	            releases.insert(historyBatchId, measurement.id(), releaser, releasedAt);
129	            jointReleases.insertItem(jointBatchId, jointBatchKey, new JointReleaseItem(
130	                    0L, jointBatchId, jointBatchKey, measurement.id(), measurement.measurementKey(),
131	                    measurement.instrumentId(), measurement.certificateId(), measurement.computedValue(),
132	                    releaser, releasedAt));
133	        }
134	        return new JointReleaseResponse(jointBatchKey, requestId, releaser, releasedAt,
135	                List.copyOf(orderedKeys));
136	    }
137	
138	    /**
139	     * 按 jointBatchKey 查询不可变联合放行记录及按测量键字典序稳定排序的明细；不存在 404。
140	     */
141	    @Transactional(readOnly = true)
142	    public JointReleaseDetailResponse detail(String jointBatchKey) {
143	        String key = Inputs.requireText(jointBatchKey, "jointBatchKey");
144	        JointReleaseBatch batch = jointReleases.findBatchByJointKey(key)
145	                .orElseThrow(() -> ApiException.notFound("联合放行批次不存在: " + key));
146	        List<JointReleaseItemResponse> items = jointReleases.findItemsByJointBatchId(batch.id()).stream()
147	                .map(item -> new JointReleaseItemResponse(
148	                        item.measurementKey(),
149	                        item.instrumentId(),
150	                        item.certificateId(),
151	                        DtoMapper.format(item.computedValue()),
152	                        item.releasedBy(),
153	                        item.releasedAt()))
154	                .toList();
155	        return new JointReleaseDetailResponse(batch.jointBatchKey(), batch.requestId(),
156	                batch.releasedBy(), batch.releasedAt(), items);
157	    }
158	
159	    /** 校验条数（2～20）与批内唯一性，返回去空白后的请求顺序列表。 */
160	    private List<String> requireKeys(List<String> keys) {
161	        if (keys == null || keys.size() < MIN_BATCH_SIZE || keys.size() > MAX_BATCH_SIZE) {
162	            throw ApiException.badRequest("联合批次放行条数必须为 " + MIN_BATCH_SIZE + "～" + MAX_BATCH_SIZE);
163	        }
164	        List<String> ordered = keys.stream().map(k -> Inputs.requireText(k, "keys[]")).toList();
165	        Set<String> distinct = new HashSet<>(ordered);
166	        if (distinct.size() != ordered.size()) {
167	            throw ApiException.badRequest("联合批次放行包含重复测量键");
168	        }
169	        return ordered;
170	    }
171	
172	    /**
173	     * 阶段一：不加锁读取每条测量当前状态、判定结果与关联证书有效性。
174	     * 任一不满足收集逐条原因，最后整批 422；全部通过才放行进入加锁阶段。
175	     */
176	    private void validateSnapshot(List<String> orderedKeys, String releaser) {
177	        List<ItemFailure> failures = new ArrayList<>();
178	        for (String key : orderedKeys) {
179	            Measurement measurement = measurements.findByKey(key).orElse(null);
180	            if (measurement == null) {
181	                failures.add(new ItemFailure(key, List.of("MEASUREMENT_NOT_FOUND")));
182	                continue;
183	            }
184	            Certificate cert = certificates.findById(measurement.certificateId())
185	                    .orElseThrow(() -> ApiException.conflict("CERTIFICATE_MISSING",
186	                            "测量关联的证书不存在: " + measurement.certificateId()));
187	            List<String> reasons = ReleaseRules.evaluate(measurement, cert, releaser);
188	            if (!reasons.isEmpty()) {
189	                failures.add(new ItemFailure(key, reasons));
190	            }
191	        }
192	        if (!failures.isEmpty()) {
193	            throw new JointBatchRejectedException(failures);
194	        }
195	    }
196	
197	    /**
198	     * 阶段二：测量键、证书 ID 各自按字典序加行锁（避免跨批次/跨入口死锁），重新读取并复核。
199	     * 任何一条与阶段一快照不一致或不再满足条件，说明存在并发裁决，整批 409 回滚。
200	     */
201	    private List<Measurement> lockAndRecheck(List<String> orderedKeys, String releaser) {
202	        List<Measurement> lockedMeasurements = new ArrayList<>();
203	        for (String key : orderedKeys.stream().sorted().toList()) {
204	            Measurement measurement = measurements.findByKeyForUpdate(key)
205	                    .orElseThrow(() -> ApiException.conflict("JOINT_BATCH_CONCURRENT_CONFLICT",
206	                            "联合批次校验后测量状态发生并发变化: " + key));
207	            lockedMeasurements.add(measurement);
208	        }
