                .map(item -> new JointReleaseItemResponse(
                        item.measurementKey(),
                        item.instrumentId(),
                        item.certificateId(),
                        DtoMapper.format(item.computedValue()),
                        item.releasedBy(),
                        item.releasedAt()))
